#
# run_forwardKernelTB_v2023.py
#
# NOTE: this targets the *v2023.1* self-contained (non-DPI) testbench flow --
# forward_kernel_tb, generated by v2023.1 bambu's --generate-tb=<file.xml>
# mechanism (see test.xml/gen_test_xml.py) and built by
# verilator-sst/output-v2023-seed7/cmake.sh with -DENABLE_CUSTOM_MODULE=ON.
# It is unrelated to the modern-bambu DPI-C flow that run_forwardKernelTB.py
# exercises (forward_kernel_testbench.c, output/, verilog_output/).
#
# Like run_forwardKernelTB.py, this just toggles the "clock" SST::Link enough
# times for the self-contained testbench's internal FSM to run to completion;
# all stimulus (from test_seed7.xml), memory, and result-checking are inside
# forward_kernel_tb itself (see output-v2023-seed7/testbench_forward_kernel_tb.v),
# which reports PASS/FAIL to stdout and to
# output-v2023-seed7/results.txt (relative to the CURRENT WORKING DIRECTORY
# bambu ran in when it generated the testbench -- the path is baked into the
# generated Verilog as an absolute path, not derived from where this script
# or SST are run from).
#
# Usage:
#   sst run_forwardKernelTB_v2023.py -- [--cycles N] [--verbose N]
#
# The v2023.1 self-contained testbench runs many more cycles than the DPI
# flow's ~12k (bambu's XML-testbench simulation reported 17192 cycles for
# this kernel); the default --cycles below is generously above that. If
# stdout shows "Sim: Simulation exceeds <N> cycles", raise --cycles.
#

import argparse
import os
import sys

import sst

# ---------------------------------------------------------------
# Point SST at the element libraries built under
# verilator-sst/output-v2023-seed7, without clobbering any SST_LIB_PATH
# entries the user already set.
# ---------------------------------------------------------------
THIS_DIR = os.path.dirname(os.path.abspath(__file__))
BUILD_DIR = os.path.join(THIS_DIR, "verilator-sst", "output-v2023-seed7")

REQUIRED_LIB_DIRS = [
    BUILD_DIR,                                                             # verilatorsstforwardKernelTB
    os.path.join(BUILD_DIR, "verilator-sst-element"),                      # verilatorcomponent
    os.path.join(BUILD_DIR, "test", "test_elements", "verilator-test-link"),  # verilatortestlink
]

existingLibPaths = [p for p in os.environ.get("SST_LIB_PATH", "").split(":") if p]
for path in REQUIRED_LIB_DIRS:
    if path not in existingLibPaths:
        existingLibPaths.append(path)
os.environ["SST_LIB_PATH"] = ":".join(existingLibPaths)

# ---------------------------------------------------------------
# CLI args (passed after "--" on the sst command line)
# ---------------------------------------------------------------
parser = argparse.ArgumentParser(description="Exercise verilatorsstforwardKernelTB (v2023.1 self-contained testbench) over its clock link")
parser.add_argument("--cycles", type=int, default=40000,
                     help="Number of clock cycles to run (default: 40000)")
parser.add_argument("--verbose", type=int, default=1,
                     help="VerilatorTestLink verbosity level (default: 1)")
args = parser.parse_args(sys.argv[1:])

NUM_CYCLES = args.cycles

# ---------------------------------------------------------------
# Test op stream: one full clock pulse (high then low) per cycle
# ---------------------------------------------------------------
testOps = []
for i in range(NUM_CYCLES):
    testOps.append(f"clock:write:1:{i}")
    testOps.append(f"clock:write:0:{i}")

# ---------------------------------------------------------------
# VerilatorTestLink drives the "clock" link; with no model subcomponent
# of its own it registers as the (a) primary component.
# ---------------------------------------------------------------
tester = sst.Component("tester0", "verilatortestlink.VerilatorTestLink")
tester.addParams({
    "verbose": args.verbose,
    "clockFreq": "1GHz",
    "num_ports": 1,
    "portMap": ["clock:0:1:2"],   # name:id:size(bytes):direction(2=writeable)
    "testOps": testOps,
    "numCycles": NUM_CYCLES,
})

# ---------------------------------------------------------------
# VerilatorComponent hosts the verilated forward_kernel_tb model
# ---------------------------------------------------------------
dut = sst.Component("dut0", "verilatorcomponent.VerilatorComponent")
dut.addParams({
    "numCycles": NUM_CYCLES,
    "verbose": args.verbose,
})
model = dut.setSubComponent("model", "verilatorsstforwardKernelTB.VerilatorSSTforwardKernelTB")
model.addParams({
    "useVPI": False,
    "clockFreq": "1GHz",
    "clockPort": "clock",
    "verbose": args.verbose,
})

# ---------------------------------------------------------------
# Wire the tester's port0 to the model's "clock" link
# ---------------------------------------------------------------
link = sst.Link("clock_link")
link.connect((tester, "port0", "0ns"), (model, "clock", "0ns"))
